    id: "econ-2024-hl-q12-c-ii", topicId: "economics-2-2", conceptId: "demerit-goods",
    section: "B", questionRef: "2024 HL Q12(c)(ii)",
    questionText: "Cigarettes are classified as demerit goods. Outline one possible effect of the demerit good markets.",
    tariffModel: {"kind":"bestNofParts","notation":"1 @ 4","answer":1,"ofParts":5,"perPart":4}, totalMarks: 4,
